package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLong;import java.util.function.*;
/** One coalesced off-main reader and an owned, nonce-fenced notification receipt. */
final class SmartBedtimeRuntime {
 interface Journal{SharedPreferences open(Context c);}interface Projection{long next(Context c,Alarm a,long now,ZoneId zone);}
 interface Output{String access(Context c);void schedule(Context c,String nonce,long at);void cancel(Context c);void show(Context c);}
 static final String ACTION="org.sleepwell.SMART_BEDTIME";static final long LATE=15*60000L;
 static final Output PLATFORM=new Output(){public String access(Context c){if(!Scheduler.allowed(c))return "Allow Alarms & reminders to schedule this reminder.";NotificationManager nm=c.getSystemService(NotificationManager.class);if(!nm.areNotificationsEnabled())return "Allow notifications to see bedtime reminders.";NotificationChannel channel=nm.getNotificationChannel(Notifications.BED);return channel!=null&&channel.getImportance()==NotificationManager.IMPORTANCE_NONE?"The Bedtime reminders notification channel is blocked.":"";}public void schedule(Context c,String nonce,long at){c.getSystemService(AlarmManager.class).setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending(c,nonce,at));}public void cancel(Context c){c.getSystemService(AlarmManager.class).cancel(pending(c,"",0));}public void show(Context c){Notifications.channels(c);c.getSystemService(NotificationManager.class).notify(300,new Notification.Builder(c,Notifications.BED).setSmallIcon(R.drawable.ic_moon).setContentTitle("Time to wind down").setContentText("Your bedtime reminder is based on the next alarm and your saved goal.").setContentIntent(Notifications.home(c)).setAutoCancel(true).build());}};
 static Output output=PLATFORM;static Journal journal=c->c.getSharedPreferences("sleepwell-smart-bedtime",0);static Projection projection=AlarmSkips::next;static LongSupplier clock=System::currentTimeMillis;static Supplier<ZoneId> zone=ZoneId::systemDefault;
 static final class Snapshot{final SleepPlan plan;final SmartBedtime.Result result;final boolean tracking;final String access;Snapshot(SleepPlan p,SmartBedtime.Result r,boolean tracking,String access){plan=p;result=r;this.tracking=tracking;this.access=access;}}
 private static final ExecutorService worker=Executors.newSingleThreadExecutor(r->new Thread(r,"SleepWell smart bedtime"));private static final AtomicLong generation=new AtomicLong();private static boolean queued,dirty;private static Request latest;private static SharedPreferences.OnSharedPreferenceChangeListener listener;private static SharedPreferences observed,delays;
 private static final class Request{final Context c;final Records.Factory records;final SleepPlans.Factory plans;final TrackingDelaySettings.Factory delay;final Journal journal;final Output output;final Projection projection;final LongSupplier clock;final Supplier<ZoneId> zone;Request(Context context){c=context.getApplicationContext();records=Records.factory;plans=SleepPlans.factory;delay=TrackingDelaySettings.factory;journal=SmartBedtimeRuntime.journal;output=SmartBedtimeRuntime.output;projection=SmartBedtimeRuntime.projection;clock=SmartBedtimeRuntime.clock;zone=SmartBedtimeRuntime.zone;}}
 static Snapshot preview(Context c,SleepPlan draft){return read(new Request(c),draft);}
 private static Snapshot read(Request q,SleepPlan draft){SleepPlan p=draft==null?new SleepPlans.Repository(q.plans.open(q.c)).load():draft.copy();long now=q.clock.getAsLong();ZoneId z=q.zone.get();int delay=new TrackingDelaySettings(q.delay.open(q.c)).minutes();List<Alarm> alarms;List<RecordEntry> records;try(Store store=q.records.open(q.c)){android.database.sqlite.SQLiteDatabase db=store.getReadableDatabase();db.beginTransactionNonExclusive();try{alarms=store.alarms();records=new ArrayList<>(Records.all(store));records.removeIf(r->{try{SensorProvenance.validate(r.sensor,r.sensorConfig);return false;}catch(IllegalArgumentException invalid){return true;}});db.setTransactionSuccessful();}finally{db.endTransaction();}}SmartBedtime.Result result=SmartBedtime.calculate(p,alarms,records,now,z,delay,(a,n,t)->q.projection.next(q.c,a,n,t));return new Snapshot(p,result,TrackingService.running||Prefs.flag(q.c,"tracking"),q.output.access(q.c));}
 static void changed(Context c){try{if(SleepPlans.load(c).smartBedtime)reconcile(c);}catch(RuntimeException ignored){}}
 static void reconcile(Context c){if(output==PLATFORM&&(Records.factory!=Records.PRODUCTION||SleepPlans.factory!=SleepPlans.PRODUCTION))return;long next=generation.incrementAndGet();if(next<=0)return;synchronized(SmartBedtimeRuntime.class){latest=new Request(c);dirty=true;if(queued)return;queued=true;}worker.execute(SmartBedtimeRuntime::refreshLoop);}
 private static void refreshLoop(){for(;;){Request q;long version;synchronized(SmartBedtimeRuntime.class){q=latest;dirty=false;version=generation.get();}refresh(q,version);synchronized(SmartBedtimeRuntime.class){if(dirty)continue;queued=false;return;}}}
 private static void status(SharedPreferences p,String value){if(!p.edit().putString("status",value).commit())throw new IllegalStateException("Reminder status could not be stored.");}
 private static void clear(SharedPreferences p,String value){if(!p.edit().remove("nonce").remove("at").remove("proof").remove("identity").putString("status",value).commit())throw new IllegalStateException("Reminder ownership could not be stored.");}
 private static void refresh(Request q,long version){SharedPreferences saved=q.journal.open(q.c);try{SleepPlan plan=new SleepPlans.Repository(q.plans.open(q.c)).load();if(!plan.smartBedtime||!plan.reminder){clear(saved,"Smart Bedtime is off.");q.output.cancel(q.c);return;}Snapshot s=read(q,plan);if(version!=generation.get())return;SmartBedtime.Result r=s.result;String problem=!s.access.isEmpty()?s.access:s.tracking?"Reminder suppressed while tracking.":!r.issue.isEmpty()?r.issue:r.identity.equals(saved.getString("consumed",""))?"Already handled this alarm's bedtime reminder.":r.at<=q.clock.getAsLong()?"The calculated reminder time has passed. The wake-up alarm is unchanged.":"";if(!problem.isEmpty()){clear(saved,problem);q.output.cancel(q.c);return;}String nonce=UUID.randomUUID().toString();if(!saved.edit().putString("nonce",nonce).putLong("at",r.at).putString("proof",r.proof).putString("identity",r.identity).putString("status","Scheduling reminder…").commit())throw new IllegalStateException("Reminder ownership could not be saved.");if(version!=generation.get()){clear(saved,"Recalculating reminder…");return;}q.output.schedule(q.c,nonce,r.at);status(saved,"Reminder scheduled.");}catch(RuntimeException failure){try{clear(saved,"Reminder needs attention: "+message(failure));q.output.cancel(q.c);}catch(RuntimeException ignored){}}}
 static void deliver(Context c,String nonce,long at,Runnable completed){Request q=new Request(c);if(q.output==PLATFORM&&(q.records!=Records.PRODUCTION||q.plans!=SleepPlans.PRODUCTION)){completed.run();return;}worker.execute(()->{try{deliver(q,nonce,at);}finally{completed.run();}});}
 private static void deliver(Request q,String nonce,long at){SharedPreferences saved=q.journal.open(q.c);try{if(nonce==null||nonce.isEmpty()||!nonce.equals(saved.getString("nonce",""))||at!=saved.getLong("at",0))return;long version=generation.get(),now=q.clock.getAsLong();if(now<at-1000)return;if(now-at>LATE){clear(saved,"Reminder missed its delivery window. Wake-up alarm unchanged.");return;}Snapshot s=read(q,null);SmartBedtime.Result r=s.result;if(r.fallback&&s.plan.nextReminder(at-1,q.zone.get())==at)r=new SmartBedtime.Result(at,0,0,0,0,0,r.observed,r.shortfall,true,"",s.plan,q.zone.get());if(version!=generation.get()||!s.plan.reminder||!s.plan.smartBedtime||!s.access.isEmpty()||!r.proof.equals(saved.getString("proof",""))){reconcile(q.c);return;}if(r.identity.equals(saved.getString("consumed","")))return;if(!saved.edit().putString("consumed",r.identity).remove("nonce").remove("at").remove("proof").remove("identity").putString("status",s.tracking?"Reminder suppressed while tracking.":"Reminder claimed for delivery.").commit())throw new IllegalStateException("Reminder receipt could not be saved.");if(s.tracking||version!=generation.get())return;q.output.show(q.c);status(saved,"Reminder shown.");}catch(RuntimeException failure){try{clear(saved,"Reminder needs attention: "+message(failure));}catch(RuntimeException ignored){}}}
 static void observe(Context c){if(listener!=null)return;Context app=c.getApplicationContext();observed=Prefs.of(app);delays=app.getSharedPreferences("sleepwell-tracking-delay",0);listener=(p,key)->{if(p==delays&&"minutes".equals(key)||p==observed&&(key==null||Set.of("goal","bedtime","bedReminder","bedReminderAdvance","smartBedtime","noAlarmBedtime","planRevision","tracking").contains(key)))reconcile(app);};observed.registerOnSharedPreferenceChangeListener(listener);delays.registerOnSharedPreferenceChangeListener(listener);if(observed.getBoolean("smartBedtime",false))reconcile(app);}
 static void drain(long timeout)throws Exception{long end=System.nanoTime()+TimeUnit.MILLISECONDS.toNanos(timeout);for(;;){worker.submit(()->{}).get(timeout,TimeUnit.MILLISECONDS);synchronized(SmartBedtimeRuntime.class){if(!queued)return;}if(System.nanoTime()>end)throw new TimeoutException("Smart Bedtime worker busy");}}
 private static PendingIntent pending(Context c,String nonce,long at){return PendingIntent.getBroadcast(c,7463,new Intent(c,SmartBedtimeReceiver.class).setAction(ACTION).putExtra("nonce",nonce).putExtra("at",at),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private static String message(RuntimeException e){return e.getMessage()==null?"Scheduling unavailable.":e.getMessage();}
 private SmartBedtimeRuntime(){}
}
